#!/usr/bin/env python3

"""inject_font.py <repo> — patch font branch, widths, and atlas."""

import base64
import re
import sys
from pathlib import Path

FONT_ATLAS_BYTES = """

""".strip()

WIDTHS = {
    "0": 10, "1": 8, "2": 9, "3": 10, "4": 10,
    "5": 10, "6": 10, "7": 9, "8": 10, "9": 10,
    "A": 10, "B": 9, "C": 9, "D": 10, "E": 8, "F": 8, "G": 10, "H": 10,
    "I": 5, "J": 7, "K": 8, "L": 8, "M": 11, "N": 9, "O": 10, "P": 8,
    "Q": 10, "R": 8, "S": 9, "T": 8, "U": 9, "V": 9, "W": 12, "X": 8,
    "Y": 8, "Z": 9,
    "a": 7, "b": 8, "c": 7, "d": 8, "e": 7, "f": 6, "g": 7, "h": 7,
    "i": 4, "j": 6, "k": 7, "l": 5, "m": 11, "n": 7, "o": 8, "p": 7,
    "q": 8, "r": 5, "s": 7, "t": 5, "u": 7, "v": 8, "w": 11, "x": 8,
    "y": 7, "z": 7,
    " ": 6,
    "!": 4, '"': 9, "'": 6, "(": 11, ")": 8, ",": 6, "-": 11, ".": 6,
    ":": 8, "<": 10, "=": 11, ">": 10, "?": 10,
}

BRANCH_VRAM = 0x80090294
BRANCH_HEX = "14a00007"
BRANCH_MNEMONIC = "bnez"

TABLE_VRAM = 0x80106AF4
TABLE_SIZE = 0x100

ATLAS_FILE = "segment_00BCD000.bin"
ATLAS_OFFSET = 0x128
ATLAS_SIZE = 0x6000

ADDR_RE = re.compile(r"/\*\s*[0-9A-Fa-f]+\s+([0-9A-Fa-f]+)\s+([0-9A-Fa-f]+)")
BYTE_RE = re.compile(r"/\*\s*\*?[0-9A-Fa-f]+\s+([0-9A-Fa-f]+)\s*\*/\s*\.byte\s+0x([0-9A-Fa-f]{2})")


def asm_files(repo):
    root = repo / "asm" / "jp"
    if not root.exists():
        sys.exit(f"error: {root} not found")
    yield from root.rglob("*.s")


def patch_branch(repo):
    target = f"{BRANCH_VRAM:08x}"

    for path in asm_files(repo):
        lines = path.read_text(errors="ignore").splitlines(keepends=True)

        for i, line in enumerate(lines):
            m = ADDR_RE.search(line)
            if not m or m.group(1).lower() != target:
                continue

            line = re.sub(
                rf"(/\*\s*[0-9A-Fa-f]+\s+{target}\s+)[0-9A-Fa-f]{{8}}",
                rf"\g<1>{BRANCH_HEX}",
                line,
                count=1,
                flags=re.IGNORECASE,
            )
            line = re.sub(
                r"\b(?:beqz|bnez)\b",
                BRANCH_MNEMONIC,
                line,
                count=1,
                flags=re.IGNORECASE,
            )

            lines[i] = line
            path.write_text("".join(lines))
            print(f"[branch] {path}:{i + 1}")
            return

    sys.exit(f"error: no line found at VRAM {BRANCH_VRAM:08X}")


def find_table(repo):
    target = f"{TABLE_VRAM:08x}"
    best_path = None
    best = {}

    for path in asm_files(repo):
        text = path.read_text(errors="ignore")
        if target not in text.lower():
            continue

        values = {}
        for m in BYTE_RE.finditer(text):
            addr = int(m.group(1), 16)
            if TABLE_VRAM <= addr < TABLE_VRAM + TABLE_SIZE:
                values[addr] = int(m.group(2), 16)

        if len(values) > len(best):
            best_path = path
            best = values

    return best_path


def patch_table(repo):
    path = find_table(repo)
    if not path:
        sys.exit(f"error: no width table found at VRAM {TABLE_VRAM:08X}")

    lines = path.read_text().splitlines(keepends=True)

    for ch, width in WIDTHS.items():
        addr = TABLE_VRAM + ord(ch)
        target = f"{addr:08x}"
        reduction = 12 - width

        for i, line in enumerate(lines):
            m = BYTE_RE.search(line)
            if not m or m.group(1).lower() != target:
                continue

            lines[i] = re.sub(
                r"(\.byte\s+)0x[0-9A-Fa-f]{2}",
                rf"\g<1>0x{reduction:02X}",
                line,
                count=1,
            )
            break
        else:
            sys.exit(f"error: missing width entry for {ch!r} at VRAM {target}")

    path.write_text("".join(lines))
    print(f"[table] {len(WIDTHS)} entries written")


def patch_atlas(repo):
    path = repo / "assets" / "jp" / ATLAS_FILE

    if not path.exists():
        sys.exit(f"error: {path} not found")

    fixed = base64.b64decode(FONT_ATLAS_BYTES)
    if len(fixed) != ATLAS_SIZE:
        sys.exit(
            f"error: fixed atlas is {len(fixed):#x} bytes, expected {ATLAS_SIZE:#x}"
        )

    data = bytearray(path.read_bytes())
    end = ATLAS_OFFSET + ATLAS_SIZE

    if len(data) < end:
        sys.exit(f"error: {path} is too small for the atlas")

    data[ATLAS_OFFSET:end] = fixed
    path.write_bytes(data)

    print(f"[atlas] wrote {ATLAS_SIZE:#x} bytes at offset {ATLAS_OFFSET:#x}")


def main():
    if len(sys.argv) != 2:
        sys.exit("usage: python3 inject_font.py <repo>")

    repo = Path(sys.argv[1]).expanduser().resolve()

    patch_branch(repo)
    patch_table(repo)
    patch_atlas(repo)

    print(f"done: run 'make' in {repo}")


if __name__ == "__main__":
    main()